import React, { useEffect, useRef, useState } from "react";
import { ArrowUpRight } from "lucide-react";
import CoffeeCup from "./coffeeCup";
import TerminalButtonLabel from "./terminalButtonLabel";
import site from "../../config";
import { track } from "../lib/analytics";

const configuredUrl = process.env.GATSBY_SUPPORT_URL ?? site.supportUrl;
const label = site.supportLabel || "Support the blog";
const supportUrl = (() => {
  try {
    const url = new URL(configuredUrl);
    return url.protocol === "https:" && !url.username && !url.password
      ? url.href
      : null;
  } catch {
    return null;
  }
})();

export function SupportLink({ placement = "footer", slug, className, terminal = false }) {
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [attention, setAttention] = useState(false);
  const interaction = useRef({ hovered: false, focused: false });
  const signalHover = () => {
    if (placement === "header") window.dispatchEvent(new CustomEvent("bb:support-hover", { detail: interaction.current.hovered || interaction.current.focused }));
  };
  useEffect(() => {
    if (placement !== "header") return undefined;
    const update = (event) => setAttention(Boolean(event.detail));
    window.addEventListener("bb:coffee-attention", update);
    return () => window.removeEventListener("bb:coffee-attention", update);
  }, [placement]);
  if (!supportUrl) return null;
  return (
    <a
      className={["support-link", className].filter(Boolean).join(" ")}
      data-coffee-attention={attention}
      href={supportUrl}
      target="_blank"
      rel="noopener noreferrer"
      onPointerEnter={(event) => {
        if (event.pointerType === "touch") return;
        interaction.current.hovered = true;
        setHovered(true);
        signalHover();
      }}
      onPointerLeave={() => {
        interaction.current.hovered = false;
        setHovered(false);
        signalHover();
      }}
      onFocus={(event) => {
        interaction.current.focused = event.currentTarget.matches(":focus-visible");
        setFocused(interaction.current.focused);
        signalHover();
      }}
      onBlur={() => {
        interaction.current.focused = false;
        setFocused(false);
        signalHover();
      }}
      onClick={() => {
        window.dispatchEvent(new CustomEvent("bb:support-activate"));
        track("support_click", {
          placement,
          ...(slug ? { article_slug: slug } : {}),
        });
      }}
    >
      {placement === "header" && <span className="coffee-attention-halo" aria-hidden="true" />}
      <CoffeeCup size={placement === "header" ? 28 : 22} active={hovered || focused} attention={attention} />
      {terminal ? <TerminalButtonLabel label={label} prompt={false} /> : label}
      {!terminal && <ArrowUpRight size={15} aria-hidden="true" />}
      <span className="sr-only"> (opens in a new tab)</span>
    </a>
  );
}

export default function SupportCard({ slug }) {
  if (!supportUrl) return null;
  return (
    <aside className="support-card" aria-label="Support BrightBytes">
      <div className="support-icon" aria-hidden="true">
        <CoffeeCup size={30} />
      </div>
      <div className="support-copy">
        <h2>Did this help you build something?</h2>
        <p>
          If these notes saved you some time, you can buy me a coffee.
          Your support helps me keep experimenting and sharing what I learn.
        </p>
        <SupportLink
          className="button support-button"
          terminal
          placement="article"
          slug={slug}
        />
        <span className="support-note">Always optional. Thanks for reading.</span>
      </div>
    </aside>
  );
}
