import React, { useEffect, useRef, useState } from "react";
import { Link, navigate } from "gatsby";
import { Moon, Sun, Search, Terminal, Menu, X } from "lucide-react";
import GitHubMark from "../githubMark";
import { SupportLink } from "../support";

const typing = (element) =>
  element?.closest?.("input, textarea, select, [contenteditable=''], [contenteditable='true']");

export default function Header({ support = true }) {
  const [theme, setTheme] = useState("light");
  const [menuOpen, setMenuOpen] = useState(false);
  const header = useRef(null);
  const menuButton = useRef(null);
  useEffect(() => {
    const media = window.matchMedia("(prefers-color-scheme: dark)");
    const sync = () => {
      let saved;
      try {
        saved = localStorage.getItem("bb-theme");
      } catch {}
      const next = saved || (media.matches ? "dark" : "light");
      document.documentElement.dataset.theme = next;
      setTheme(next);
    };
    sync();
    media.addEventListener("change", sync);
    return () => media.removeEventListener("change", sync);
  }, []);
  // "/" jumps to search from anywhere that is not a text field.
  useEffect(() => {
    const onKey = (event) => {
      if (event.key !== "/" || event.metaKey || event.ctrlKey || event.altKey) return;
      if (event.defaultPrevented || typing(event.target)) return;
      event.preventDefault();
      const field = document.getElementById("article-search");
      if (field) field.focus();
      else navigate("/search/", { state: { focusSearch: true } });
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);
  // The small-screen menu closes on Escape or a tap outside the header.
  useEffect(() => {
    if (!menuOpen) return undefined;
    const onKey = (event) => {
      if (event.key !== "Escape") return;
      setMenuOpen(false);
      menuButton.current?.focus();
    };
    const onPointer = (event) => {
      if (!header.current?.contains(event.target)) setMenuOpen(false);
    };
    window.addEventListener("keydown", onKey);
    window.addEventListener("pointerdown", onPointer);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("pointerdown", onPointer);
    };
  }, [menuOpen]);
  function toggleTheme() {
    const next = theme === "dark" ? "light" : "dark";
    setTheme(next);
    document.documentElement.dataset.theme = next;
    try {
      localStorage.setItem("bb-theme", next);
    } catch {}
  }
  return (
    <header className="site-header" ref={header} data-menu-open={menuOpen}>
      <div className="header-inner">
        <Link to="/" className="brand" aria-label="BrightBytes home">
          <span className="brand-mark">
            <Terminal size={19} />
          </span>
          <span>
            bright<span className="brand-light">bytes</span>
            <span className="brand-dot">!</span>
          </span>
        </Link>
        <nav id="site-nav" aria-label="Main navigation">
          <Link to="/blog/" activeClassName="nav-active" partiallyActive>
            Articles
          </Link>
          <Link to="/projects/" activeClassName="nav-active" partiallyActive>
            Projects
          </Link>
          <Link to="/about/" activeClassName="nav-active">
            About
          </Link>
          <Link to="/contact/" activeClassName="nav-active">
            Contact
          </Link>
          {support && (
            <SupportLink className="btn-key-term header-support" placement="header" terminal />
          )}
        </nav>
        <div className="header-actions">
          <a
            href="https://github.com/AhmadRoshanfar"
            className="icon-button header-github"
            aria-label="Ahmad on GitHub"
            title="Ahmad on GitHub"
          >
            <GitHubMark size={21} aria-hidden="true" focusable="false" />
          </a>
          <Link
            to="/search/"
            state={{ focusSearch: true }}
            className="icon-button"
            aria-label="Search articles"
            aria-keyshortcuts="/"
            title="Search articles (press /)"
          >
            <Search size={19} />
          </Link>
          <span className="divider" />
          <button
            className="icon-button"
            onClick={toggleTheme}
            aria-label={`Switch to ${theme === "light" ? "dark" : "light"} theme`}
          >
            {theme === "light" ? <Moon size={18} /> : <Sun size={18} />}
          </button>
          <button
            ref={menuButton}
            className="icon-button menu-button"
            aria-expanded={menuOpen}
            aria-controls="site-nav"
            onClick={() => setMenuOpen((open) => !open)}
          >
            {menuOpen ? <X size={20} aria-hidden="true" /> : <Menu size={20} aria-hidden="true" />}
            <span className="sr-only">Menu</span>
          </button>
        </div>
      </div>
    </header>
  );
}
