import React from "react";

export default function TerminalButtonLabel({ label, command, cursor = false, cursorActive = true, prompt = true }) {
  return (
    <span className="terminal-button-label">
      {prompt && <span className="prompt" aria-hidden="true">&gt;</span>}
      <span aria-hidden="true">{command || label.toLowerCase().replaceAll(" ", "_")}</span>
      {cursor && <span className="cursor" aria-hidden="true" style={cursorActive ? undefined : { animationPlayState: "paused" }} />}
      <span className="sr-only">{label}</span>
    </span>
  );
}
