import React, { useCallback, useEffect, useState } from "react";
import useIllustrationRuntime from "./useIllustrationRuntime";

function Thanks({ Animation }) {
  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);
  const handleReady = useCallback(() => setReady(true), []);
  const handleError = useCallback(() => setFailed(true), []);
  return (
    <span className="coffee-thanks" aria-hidden="true">
      <span className="coffee-thanks-fallback" hidden={ready && !failed}>Thank You! <span>♥</span></span>
      {Animation && !failed && (
        <Animation
          src="/animations/coffee-cup.riv"
          artboard="Thanks"
          stateMachine="Thanks"
          onReady={handleReady}
          onError={handleError}
        />
      )}
    </span>
  );
}

export default function CoffeeCup({ size = 22, active = false, attention = false }) {
  const [hovered, setHovered] = useState(false);
  const showThanks = active || hovered;
  // The drawn cup is the default; the animated one loads on first interest.
  const [engaged, setEngaged] = useState(false);
  useEffect(() => {
    if (showThanks) setEngaged(true);
  }, [showThanks]);
  const { container, Animation } = useIllustrationRuntime(engaged);
  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);
  const handleReady = useCallback(() => setReady(true), []);
  const handleError = useCallback(() => setFailed(true), []);
  return (
    <span
      ref={container}
      className="coffee-cup"
      style={{ width: size, height: size }}
      aria-hidden="true"
      onPointerEnter={(event) => event.pointerType !== "touch" && setHovered(true)}
      onPointerLeave={() => setHovered(false)}
    >
      <span className="coffee-cup-artwork">
        <svg className="coffee-cup-fallback" hidden={Animation && ready && !failed}
             viewBox="0 0 64 64" width={size} height={size} fill="none"
             stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
          <path d="M9 59h40M46 34c18-5 17 17-1 15M13 30h34v13c0 19-34 19-34 0Z" />
          <path className="coffee-steam" opacity=".55" strokeWidth="2.3" d="M21 23c-9-6 8-9 0-16M31 23c-9-6 8-9 0-16M41 23c-9-6 8-9 0-16" />
        </svg>
        {Animation && !failed && (
          <Animation
            src="/animations/coffee-cup.riv"
            artboard="Cup"
            stateMachine="Coffee"
            inkRef={container}
            inkState={attention}
            active={showThanks}
            onReady={handleReady}
            onError={handleError}
          />
        )}
      </span>
      {showThanks && <Thanks Animation={Animation} />}
    </span>
  );
}
