import { useEffect, useRef, useState } from "react";

let runtime;
// `wanted` lets an illustration wait for a reader's interest before the
// runtime (script and WebAssembly) is downloaded.
export default function useIllustrationRuntime(wanted = true) {
  const container = useRef(null);
  const [Animation, setAnimation] = useState(null);
  const [motion, setMotion] = useState(null);
  const [visible, setVisible] = useState(false);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    const preference = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setMotion(!preference.matches);
    sync();
    preference.addEventListener("change", sync);
    const observer = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting));
    if (container.current) observer.observe(container.current);
    return () => {
      observer.disconnect();
      preference.removeEventListener("change", sync);
    };
  }, []);

  useEffect(() => {
    if (!wanted || !motion || !visible || Animation) return undefined;
    let cancelled = false;
    runtime ||= import("./riveAnimation");
    runtime.then(({ default: Component }) => {
      if (!cancelled) setAnimation(() => Component);
    }).catch(() => {
      if (!cancelled) setFailed(true);
    });
    return () => { cancelled = true; };
  }, [wanted, motion, visible, Animation]);

  return { container, Animation: motion ? Animation : null, reducedMotion: motion === false, failed };
}
